// === Tab: lorenz ===
let crawlersCount = 1000;
let trailLength = 10;
let speed = 50; // frame skip, actually

let scaleX = 12.0;
let scaleY = 100;
let scaleZ = 10.0;

// let of the attractor. let this values it becomes more interesting
let sigma = 10.0;
let r = 28.0;
let b = 8.0 / 3.0;

// actual time step
let dt = 0.001;

// just indexes
let X = 0;
let Y = 1;
let Z = 2;

let k1, k2, k3, k4;

let MAX_TRAIL = 1000;
let MAX_CRAWLERS = 1000;

// doesn't work with canvas :(
int smoothing = 0;

int explosion = 0;
float explosionForce = 400.0;

class Crawler {
  float x, y, z;
  PVector[] trail;
  int trailEnd;

  color c;

  Crawler() {
    x = random(-100, 100);
    y = random(-100, 100);
    z = random(-100, 100);
    c = color(random(255), 255, 255);

    trail = new PVector[MAX_TRAIL];
    int i;
    for(i=0; i<MAX_TRAIL; i++) {
      trail[i] = new PVector(x * scaleX + width / 2, y, -z * scaleZ + height);
    }
    trailEnd = 0;
  } 

  void awake() {
    x = random(-100, 100);
    y = random(-100, 100);
    z = random(-100, 100);
    c = color(random(100, 200), random(100, 200), random(100, 200));
    int i;
    for(i=0; i<MAX_TRAIL; i++) {
      trail[i] = new PVector(x * scaleX + width / 2, y, -z * scaleZ + height);
    }
    trailEnd = 0;
  }

  // the Runge-Kutta method
  void step(int dummyStep) {
    k1[X] = dt * dx(x, y, z);
    k1[Y] = dt * dy(x, y, z);
    k1[Z] = dt * dz(x, y, z);

    k2[X] = dt * dx(x + k1[X] / 2.0, y + k1[Y] / 2.0, z + k1[Z] / 2.0);
    k2[Y] = dt * dy(x + k1[X] / 2.0, y + k1[Y] / 2.0, z + k1[Z] / 2.0);
    k2[Z] = dt * dz(x + k1[X] / 2.0, y + k1[Y] / 2.0, z + k1[Z] / 2.0);

    k3[X] = dt * dx(x + k2[X] / 2.0, y + k2[Y] / 2.0, z + k2[Z] / 2.0);
    k3[Y] = dt * dy(x + k2[X] / 2.0, y + k2[Y] / 2.0, z + k2[Z] / 2.0);
    k3[Z] = dt * dz(x + k2[X] / 2.0, y + k2[Y] / 2.0, z + k2[Z] / 2.0);

    k4[X] = dt * dx(x + k3[X], y + k3[Y], z + k3[Z]);
    k4[Y] = dt * dy(x + k3[X], y + k3[Y], z + k3[Z]);
    k4[Z] = dt * dz(x + k3[X], y + k3[Y], z + k3[Z]);

    x = x + (k1[X] + k2[X] + k3[X]) / 6.0;
    y = y + (k1[Y] + k2[Y] + k3[Y]) / 6.0;
    z = z + (k1[Z] + k2[Z] + k3[Z]) / 6.0;

    if(!dummyStep) {
      trailEnd--;
      if(trailEnd < 0) trailEnd = MAX_TRAIL - 1;
      trail[trailEnd].set(x * scaleX + width / 2, y, -z * scaleZ + height);
    }
  }
}

Crawler[] crawlers;

void setup() {
  size(1112, 834);
  colorMode(HSB, 255)
  k1 = new float[3];
  k2 = new float[3];
  k3 = new float[3];
  k4 = new float[3];

  crawlers = new Crawler[MAX_CRAWLERS];
  int i;
  for(i=0; i<MAX_CRAWLERS; i++) {
    crawlers[i] = new Crawler(); 
  }
}

void draw() {
  background(0);
	if (frameCount%100 == 0) explode(); // no effect???
	translate(-560, -460);
	scale(2,1.5);
  int i, j;
  float px, py, pz;
  PVector v, pv;
  if(smoothing)
    smooth();
  else
    noSmooth();
  for(i=0; i<crawlersCount; i++) {

    for(j=0; j<speed; j++)
      crawlers[i].step(1);
      crawlers[i].step(0);

      // this is way faster than standard functions
      var c = document.getElementsByTagName("CANVAS")[0].getContext("2d");
      c.strokeStyle = "#"+hex(crawlers[i].c, 6);
      for(j=0; j<trailLength-1; j++) {
      v = crawlers[i].trail[(crawlers[j].trailEnd + j) % MAX_TRAIL];
      pv = crawlers[i].trail[(crawlers[j].trailEnd + j + 1) % MAX_TRAIL];
      c.lineWidth = constrain(abs(v.y) / 5, 0.2, 8);
      c.beginPath();
      c.moveTo(pv.x, pv.z);
      c.lineTo(v.x, v.z);
      c.stroke();
    }

    if(explosion)
      explode();
  }

  textSize(10);
  fill(210);
  //text("time step = "+speed+"; trail length = "+trailLength+"; smooth: "+smoothing+"; paticles: "+crawlersCount, 10, height - 15);
}

void keyReleased() {
  if(keyCode == UP && dt < 0.01) {
    dt += 0.0001;
  } 
  if(keyCode == DOWN && dt > 0.0001) {
    dt -= 0.0001;
  } 
  if(keyCode == RIGHT && speed < 100) {
    speed += 1; 
  }
  if(keyCode == LEFT && speed > 1) {
    speed -= 1; 
  }
  if(key == 't' && trailLength > 2) {
    trailLength --; 
  }
  if(key == 'T' && trailLength < MAX_TRAIL) {
    trailLength ++; 
  }
  if(key == 'c' && crawlersCount > 10) {
    crawlersCount -= 10; 
  }
  if(key == 'C' && crawlersCount < MAX_CRAWLERS) {
    int i;
    // there is a bug with awaking, but it's not critical
    for(i=crawlersCount; i<crawlersCount+10; i++)
      crawlers[i].awake();
    crawlersCount += 10; 
  }
  if(key == 's' && speed > 1) {
    speed -= 1; 
  }
  if(key == 'S' && speed < 100) {
    speed += 1; 
  }
  /*if(key == 'S' || key =='s')
    smoothing = !smoothing;*/
}

// just push particles away from cursor
function explode() {
  let mx = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) / scaleX;
  let mz = -((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height) / scaleZ;
  let dx, dz, l;
  let i;
  for(i=0; i<crawlersCount; i++) {
    dx = crawlers[i].x - mx;
    dz = crawlers[i].z - mz;

    l = explosionForce * (sq(dx) + sq(dz));
    crawlers[i].x += dx / l;
    crawlers[i].z += dz / l;
  }
}

function mousePressed() {
   explosion = 1;
}

function mouseReleased() {
   explosion = 0;
}

// equations of the system 
function dx(x, y, z) {
  return sigma * (y - x);
}

function dy(x, y, z) {
  return -x * z + r * x - y;
}

function dz(x, y, z) {
  return x * y - b * z;
}

